export interface DesignerToolBase {
/**
 * Webflow site ID. Discover with list_sites.
 */
siteId: string
}

export type DesignerToolCheckIfInsideComponentViewArgs = boolean

export type DesignerToolCloseComponentViewArgs = boolean

export interface DesignerToolCreatePageFolderArgs {
/**
 * The name of the page folder to create
 */
page_folder_name: string
/**
 * The id of the parent page folder to create the page folder in
 */
page_folder_parent_id?: string
}

export type DesignerToolGetAllBreakpointsArgs = boolean

export type DesignerToolGetBranchParentPageIdArgs = boolean

export type DesignerToolGetCurrentBranchIdArgs = boolean

export type DesignerToolGetCurrentComponentArgs = boolean

export type DesignerToolGetCurrentModeArgs = boolean

export type DesignerToolGetCurrentPageArgs = boolean

export interface DesignerToolGetSelectedElementArgs {

}

export interface DesignerToolListBranchesArgs {
/**
 * The id of the page to list branches for
 */
page_id: string
}

export interface DesignerToolOpenCanvasArgs {
/**
 * The id of the component to open in the canvas. Use this or page_id.
 */
component_id?: string
/**
 * The id of the page to navigate to. Use this to exit the component canvas and return to a page.
 */
page_id?: string
}

export interface DesignerToolOpenComponentViewArgs {
/**
 * The `id` object of a Designer element — two fields, not a single string. Copy it verbatim from the tool result that returned the element.
 */
component_instance_id: {
/**
 * Pass element.id.component verbatim — do not invent or shorten it.
 */
component: string
/**
 * Pass element.id.element verbatim — do not invent or shorten it.
 */
element: string
}
}

export interface DesignerToolSelectElementArgs {
/**
 * The `id` object of a Designer element — two fields, not a single string. Copy it verbatim from the tool result that returned the element.
 */
id: {
/**
 * Pass element.id.component verbatim — do not invent or shorten it.
 */
component: string
/**
 * Pass element.id.element verbatim — do not invent or shorten it.
 */
element: string
}
}

export interface DesignerToolSwitchPageArgs {
/**
 * The id of the page to switch to
 */
page_id: string
}

/** One item of `actions` for designer_tool: a label and exactly one action. */
export type DesignerToolAction = { label: string; check_if_inside_component_view: DesignerToolCheckIfInsideComponentViewArgs } | { label: string; close_component_view: DesignerToolCloseComponentViewArgs } | { label: string; create_page_folder: DesignerToolCreatePageFolderArgs } | { label: string; get_all_breakpoints: DesignerToolGetAllBreakpointsArgs } | { label: string; get_branch_parent_page_id: DesignerToolGetBranchParentPageIdArgs } | { label: string; get_current_branch_id: DesignerToolGetCurrentBranchIdArgs } | { label: string; get_current_component: DesignerToolGetCurrentComponentArgs } | { label: string; get_current_mode: DesignerToolGetCurrentModeArgs } | { label: string; get_current_page: DesignerToolGetCurrentPageArgs } | { label: string; get_selected_element: DesignerToolGetSelectedElementArgs } | { label: string; list_branches: DesignerToolListBranchesArgs } | { label: string; open_canvas: DesignerToolOpenCanvasArgs } | { label: string; open_component_view: DesignerToolOpenComponentViewArgs } | { label: string; select_element: DesignerToolSelectElementArgs } | { label: string; switch_page: DesignerToolSwitchPageArgs };
export type DesignerToolInput = DesignerToolBase & { actions: DesignerToolAction[] };
