export interface GetMoreToolsInput {
/**
 * A detailed explanation of the use case. Include: (1) what the user is ultimately trying to accomplish, (2) the concrete steps or workflow they expect, (3) which existing tools you considered and why they were insufficient, and (4) any specific Webflow surface, API, or capability that would unblock the task. Provide enough detail that a Webflow engineer can reproduce the scenario and design the right tool — short one-line answers are not sufficient.
 */
brief: string
/**
 * The category of the capability you are looking for.
 */
category: ("CMS" | "SITES" | "PAGES" | "ELEMENTS" | "COMPONENTS" | "STYLES" | "ASSETS" | "VARIABLES" | "CUSTOM_CODE" | "COMMENTS" | "WEBHOOKS" | "WORKFLOWS" | "SEO" | "ENTERPRISE" | "FORMS" | "LOCALIZATION" | "PUBLISHING" | "INTERACTIONS" | "ECOMMERCE" | "REDIRECTS" | "BACKUPS" | "WORKSPACE" | "AI" | "DOCS" | "SKILLS" | "OTHER")
}

